/* ============================================================================
 * NextWork Theme Studio - painted wallpapers
 *
 * Most scenery in this extension is generated SVG. This file is the exception:
 * raster artwork, carried inline as a data URI because a content script cannot
 * fetch a file - the site's CSP blocks it, and web_accessible_resources would
 * widen the extension's surface for the sake of one picture.
 *
 * Sources live in art/ and are covered by the repository's licence.
 *
 * Inline means the bytes ride in every injected stylesheet, so each image is
 * downscaled and compressed hard, and the audit caps the size.
 *
 * `minRatio` is the measured contrast between body text and the brightest part
 * of the image, taken on a blurred copy - a reader reads against the local
 * average, not one pixel, which is what lets the doorway keep a bright core.
 * tools/make-wallpaper.py regenerates the whole thing and prints the number;
 * it picks the gentlest darkening that still clears the floor. The source here
 * measured 2.11:1 untouched, so this is not a tint, it is a real exposure cut.
 * ==========================================================================*/
(function (root) {
  'use strict';

  root.NWT_WALLPAPERS = {
    /* A concrete arcade at night, looking down the corridor toward a lit
     * doorway. Source: art/concrete-corridor.jpg, which measures 2.40:1 as it
     * stands - far under the floor. Exposure is cut to 0.17 in linear light to
     * bring it to 7.32:1. Regenerate with tools/make-wallpaper.py. */
    concreteCorridor: {
      minRatio: 7.32,
      width: 1600,
      height: 893,
      uri: 'data:image/jpeg;base64,'
    }
  };

})(typeof self !== 'undefined' ? self : this);
